-- Metadata SELECT only; no customer rows. Run with a read-only connection and bounded statement timeout.
-- Record Data API configuration separately: missing pgrst.db_schemas does NOT mean disabled.
select jsonb_build_object(
'captured_at', now(),
'database_version', current_setting('server_version'),
'observer_role', current_user,
'roles', (select jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypass_rls',rolbypassrls,'inherit',rolinherit,'login',rolcanlogin) order by rolname) from pg_roles where rolname in ('anon','authenticated','service_role','authenticator','postgres')),
'schemas',(select jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'anon_usage',has_schema_privilege('anon',oid,'USAGE'),'auth_usage',has_schema_privilege('authenticated',oid,'USAGE')) order by nspname) from pg_namespace where nspname !~ '^pg_' and nspname <> 'information_schema'),
'relations',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions,'anon_select',has_table_privilege('anon',c.oid,'SELECT'),'anon_insert',has_table_privilege('anon',c.oid,'INSERT'),'anon_update',has_table_privilege('anon',c.oid,'UPDATE'),'anon_delete',has_table_privilege('anon',c.oid,'DELETE'),'anon_truncate',has_table_privilege('anon',c.oid,'TRUNCATE'),'auth_select',has_table_privilege('authenticated',c.oid,'SELECT'),'auth_insert',has_table_privilege('authenticated',c.oid,'INSERT'),'auth_update',has_table_privilege('authenticated',c.oid,'UPDATE'),'auth_delete',has_table_privilege('authenticated',c.oid,'DELETE'),'auth_truncate',has_table_privilege('authenticated',c.oid,'TRUNCATE')) order by n.nspname,c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','storage','realtime') and c.relkind in ('r','p','v','m')),
'policies',(select coalesce(jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname),'[]'::jsonb) from pg_policies p where schemaname in ('public','storage','realtime')),
'functions',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity_arguments',pg_get_function_identity_arguments(p.oid),'security_definer',p.prosecdef,'owner',pg_get_userbyid(p.proowner),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'auth_execute',has_function_privilege('authenticated',p.oid,'EXECUTE')) order by p.proname),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),
'sequences',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'anon_usage',has_sequence_privilege('anon',c.oid,'USAGE'),'auth_usage',has_sequence_privilege('authenticated',c.oid,'USAGE'),'anon_update',has_sequence_privilege('anon',c.oid,'UPDATE'),'auth_update',has_sequence_privilege('authenticated',c.oid,'UPDATE')) order by c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='S'),
'default_acl',(select coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'object_type',d.defaclobjtype,'acl',d.defaclacl::text)),'[]'::jsonb) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where n.nspname='public' or d.defaclnamespace=0),
'api_role_settings',(select coalesce(jsonb_agg(jsonb_build_object('role',pg_get_userbyid(s.setrole),'settings',array(select v from unnest(s.setconfig) v where v like 'pgrst.db_schemas=%'))),'[]'::jsonb) from pg_db_role_setting s where s.setrole=(select oid from pg_roles where rolname='authenticator')),
'publications',(select coalesce(jsonb_agg(jsonb_build_object('publication',pubname,'schema',schemaname,'table',tablename) order by pubname,schemaname,tablename),'[]'::jsonb) from pg_publication_tables where schemaname='public'),
'storage_buckets',(select coalesce(jsonb_agg(jsonb_build_object('name',name,'public',public) order by name),'[]'::jsonb) from storage.buckets)
) as inventory;

select jsonb_build_object(
'columns',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type,'udt',udt_name,'nullable',is_nullable,'ordinal',ordinal_position) order by table_name,ordinal_position) from information_schema.columns where table_schema='public'),
'column_grants',(select coalesce(jsonb_agg(to_jsonb(g)),'[]'::jsonb) from information_schema.column_privileges g where table_schema='public' and grantee in ('anon','authenticated','PUBLIC')),
'constraints',(select jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'type',c.contype,'definition',pg_get_constraintdef(c.oid)) order by c.conrelid::regclass::text,c.conname) from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname='public'),
'triggers',(select coalesce(jsonb_agg(jsonb_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'definition',pg_get_triggerdef(t.oid))),'[]'::jsonb) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal)
) as structure;
